    {
      "claim": "Maraviroc fasted F was 24% at 100 mg and up to 33% at 600 mg, above the 20% threshold.",
      "card_ids": ["C16", "C21", "C45", "C55"]
    },
    {
      "claim": "L3 oral AUC/Cmax records for enalapril, perindopril, and ramipril are prodrug/metabolite exposure measurements and do not directly measure the query's F.",
